pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address admin = address(0x1);
    address newOwner = address(0x2);

    function setUp() public { 
        c = new C();
        vm.deal(admin, 1 ether);
    }

    function testRegression_property() public {
        vm.prank(admin);
        (bool ok, ) = address(c).call(abi.encodeWithSignature("setOwner(address)", newOwner));
        assertEq(c.owner(), newOwner);
    }
}

